var toggle=root.querySelector('.btnx-split-drop-toggle');
var main=root.querySelector('.btnx-split-drop-main');
var label=root.querySelector('.btnx-split-drop-mlabel');
var menu=root.querySelector('.btnx-split-drop-menu');
var items=Array.prototype.slice.call(root.querySelectorAll('.btnx-split-drop-item'));
var open=false;var mt=null;
function setOpen(v,focusSel){open=v;root.classList.toggle('btnx-split-drop-open',v);toggle.setAttribute('aria-expanded',v?'true':'false');menu.setAttribute('aria-hidden',v?'false':'true');items.forEach(function(it){it.tabIndex=v?0:-1;});if(v&&focusSel){var c=items.filter(function(it){return it.getAttribute('aria-checked')==='true';})[0]||items[0];c.focus();}}
toggle.addEventListener('click',function(){setOpen(!open,true);});
items.forEach(function(it){it.addEventListener('click',function(){items.forEach(function(o){o.setAttribute('aria-checked',o===it?'true':'false');});label.textContent=it.querySelector('.btnx-split-drop-name').textContent;setOpen(false);toggle.focus();});});
main.addEventListener('click',function(){if(main.classList.contains('btnx-split-drop-busy')){return;}var was=label.textContent;main.classList.add('btnx-split-drop-busy');label.textContent='Merging…';clearTimeout(mt);mt=setTimeout(function(){main.classList.remove('btnx-split-drop-busy');label.textContent=was;},1700);});
root.addEventListener('keydown',function(e){
  if(e.key==='Escape'&&open){setOpen(false);toggle.focus();return;}
  if(e.key!=='ArrowDown'&&e.key!=='ArrowUp'){return;}
  if(!open){if(e.target===toggle||e.target===main){setOpen(true,true);e.preventDefault();}return;}
  var i=items.indexOf(e.target);
  if(i<0){i=0;}
  var n=e.key==='ArrowDown'?(i+1)%items.length:(i-1+items.length)%items.length;
  items[n].focus();e.preventDefault();
});
root.addEventListener('focusout',function(e){if(open&&!root.contains(e.relatedTarget)){setOpen(false);}});

