js:
var btn=root.querySelector('.btnx-async-tick-btn');
var status=root.querySelector('.btnx-async-tick-status');
var idleNote='Visa ending 4417';
var attempts=0;var timers=[];
function clearAll(){timers.forEach(function(t){clearTimeout(t);});timers=[];}
btn.addEventListener('click',function(){
  if(btn.getAttribute('data-state')==='loading'){return;}
  clearAll();
  attempts++;
  btn.setAttribute('data-state','loading');
  btn.disabled=true;
  btn.setAttribute('aria-busy','true');
  status.textContent='Contacting issuer…';
  timers.push(setTimeout(function(){
    btn.disabled=false;
    btn.removeAttribute('aria-busy');
    if(attempts%2===1){
      btn.setAttribute('data-state','success');
      status.textContent='Receipt sent to sam@northwind.co';
      timers.push(setTimeout(function(){btn.setAttribute('data-state','idle');status.textContent=idleNote;},2600));
    }else{
      btn.setAttribute('data-state','error');
      status.textContent='Issuer declined · code 51';
    }
  },1500));
});

