var btn=root.querySelector('.btnx-toggle-latch-btn');
var meta=root.querySelector('.btnx-toggle-latch-meta');
var idleNote='6 sensors online · Hall, Garage, Deck';
btn.addEventListener('click',function(){
  var on=btn.getAttribute('aria-pressed')==='true';
  btn.setAttribute('aria-pressed',on?'false':'true');
  btn.classList.remove('btnx-toggle-latch-kick');
  void btn.offsetWidth;
  btn.classList.add('btnx-toggle-latch-kick');
  if(on){
    meta.textContent=idleNote;
  }else{
    var d=new Date();
    var hh=('0'+d.getHours()).slice(-2);
    var mm=('0'+d.getMinutes()).slice(-2);
    meta.textContent='Armed at '+hh+':'+mm+' · all zones reporting';
  }
});
btn.addEventListener('animationend',function(){btn.classList.remove('btnx-toggle-latch-kick');});
